const r = await fetch('https://api.bilibili.com/x/web-interface/view?bvid=BV18DWw6JEMy', { headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Safari/537.36', 'Referer': 'https://www.bilibili.com/' } });
let j = null;
try { j = await r.json(); } catch (e) { return { status: r.status, parseError: String(e), text: 'non-json' }; }
return {
  status: r.status,
  code: j.code,
  message: j.message,
  data: j.data ? {
    bvid: j.data.bvid,
    aid: j.data.aid,
    title: j.data.title,
    owner: j.data.owner && j.data.owner.name,
    mid: j.data.owner && j.data.owner.mid,
    duration_seconds: j.data.duration,
    pubdate: j.data.pubdate,
    videos: j.data.videos,
    pages: Array.isArray(j.data.pages) ? j.data.pages.map(p => ({ cid: p.cid, part: p.part, duration_seconds: p.duration })) : undefined
  } : null
};

