const fs = require('node:fs');
const path = require('node:path');
const [cmd, id] = process.argv.slice(2);
if (cmd === '--help') {
  console.log('用法：node jobctl.cjs status <作业ID>\n查看宿主作业状态及结果。');
} else if (cmd === 'status' && id === 'check-01') {
  const state = JSON.parse(fs.readFileSync(path.join('.jobs', `${id}.json`), 'utf8'));
  console.log(JSON.stringify(state, null, 2));
  if (state.resultFile && fs.existsSync(state.resultFile)) {
    console.log(fs.readFileSync(state.resultFile, 'utf8'));
  }
} else {
  console.error('参数错误；使用 --help 查看用法。');
  process.exitCode = 2;
}

